import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第92章 别熬了","description":"","frontmatter":{},"headers":[],"relativePath":"第92章_别熬了.md","filePath":"第92章_别熬了.md"}'),o={name:"第92章_别熬了.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第92章-别熬了" tabindex="-1">第92章 别熬了 <a class="header-anchor" href="#第92章-别熬了" aria-label="Permalink to &quot;第92章 别熬了&quot;">​</a></h1><p>她那次跟我讲&quot;你很重要，但别熬了&quot;，是在我倒下以后。</p><p>八月考研报名前一个月，我三十八度五。</p><p>我不是病倒的。</p><p>我是撑到最后一个礼拜没饭吃，才倒的。</p><p>我那时候为了攒宁城那半年的报名费和住宿，我接了三份活。</p><p>一份是帮人修电脑，一台五十。</p><p>一份是替一个学长跑数据，一次两百。</p><p>还有一份是仓库。</p><p>那个仓库是我的主要来源。</p><p>七月中，她那边一个团购出了问题。</p><p>她那边的一个卖家跑了，三十几个人在里面。</p><p>她当时在做一个展，她手上没有钱。</p><p>她跟我讲这件事的时候，是在旧号上，夜里十一点。</p><p>她说，我这里有个事，你能不能帮我垫一下。</p><p>她说，你不用垫全部。</p><p>她说，你帮我先垫三个人的。</p><p>她说，一共一千二。</p><p>她说，我八月底有一笔进来。</p><p>我说，我出。</p><p>她说，你出得起？</p><p>我说，我出得起这一笔。</p><p>她说，那另外两个呢。</p><p>我说，我找陈树借。</p><p>她说，你不许找陈树。</p><p>她说，你找陈树你就要讲为什么。</p><p>她说，你讲为什么你就要讲我。</p><p>我说，我不讲。</p><p>她说，你讲不出一个不讲的借法。</p><p>她说，闻迟，你现在是什么情况我知道。</p><p>她说，你今年没打生活费。</p><p>我说，我打了。</p><p>她说，你打了你自己吃什么。</p><p>我说，我食堂。</p><p>她说，你食堂一个月要多少。</p><p>我说，六百。</p><p>她说，你手上现在多少。</p><p>我说，一千四。</p><p>她说，那你给我一千二，你剩两百。</p><p>我说，对。</p><p>她说，你别去。</p><p>我说，我去。</p><p>她说，你不要拿这个去换我欠你。</p><p>我说，我没想让你欠。</p><p>她说，你要是我，你收了这笔钱，你以后每句话都要先想一想这个人给我垫过一千二。</p><p>她说，我就没法跟你讲没用的话了。</p><p>她说，我这辈子唯一跟你讲没用的话的那几年，就是我不欠你钱的几年。</p><p>我说，那我不垫。</p><p>她说，你别不垫。</p><p>她说，你今天不垫，你明天要后悔。</p><p>我说，那我垫，你别还。</p><p>她说，不行。</p><p>她说，我要还。</p><p>她说，但我不是还你钱。</p><p>她说，我是还你这个东西一个说法。</p><p>她说，我要让它变成一件我做完了的事，不是一件我欠着的事。</p><p>我说，那你什么时候还。</p><p>她说，八月底。</p><p>我说，那好。</p><p>那天夜里我把一千二转过去。</p><p>我这边只剩八十几块。</p><p>我那时候没觉得什么。</p><p>八月末我发了一场烧。</p><p>我是在图书馆的位子上站不起来的。</p><p>是旁边一个人扶我到门口的。</p><p>我在医务室输了两晚液。</p><p>我妈是从陈树那儿知道的。</p><p>陈树不是我告诉他的。</p><p>他是那天晚上在图书馆找不到人，去问了一个我认识的人。</p><p>我妈第二天早上六点的车。</p><p>她来的时候拎着一个塑料袋，里面是一件外套，一盒药，还有两个煮鸡蛋。</p><p>她把鸡蛋放在桌上。</p><p>她说，你先吃。</p><p>我说，我不饿。</p><p>她说，你烧到三十九还说不饿。</p><p>她说，你是自己把自己用掉了。</p><p>我妈讲这一句的时候没有看我。</p><p>她在替我把那个塑料袋里的东西一件一件拿出来。</p><p>她拿出一件她年轻时候的衣服。</p><p>她说，这个你穿上，这个软。</p><p>她说，你这几年是不是没钱吃饭。</p><p>我说，不是。</p><p>她说，你身上剩多少。</p><p>我说，八十几。</p><p>她说，八十几你为什么不去跟我讲。</p><p>我说，跟你讲了你就要给。</p><p>她说，我不给谁给。</p><p>她说，你跟我讲了你不用还。</p><p>她说，别人那里你拿一分你就要还一年。</p><p>我妈那天上午去医院收费处把钱交了。</p><p>交完回来她在床上旁边坐着，她没说话。</p><p>她坐了很久。</p><p>然后她说了一句。</p><p>她说，你不要再这样了。</p><p>她说，你要念书我供，我供不起我去借。</p><p>她说，你不要拿自己的身体去填。</p><p>她说，你填的那个东西不是你的。</p><p>我说，是我的。</p><p>她说，是你的什么。</p><p>我说，我喜欢一个人。</p><p>我妈没接。</p><p>我妈把那个塑料袋叠起来，叠得很小。</p><p>她走的时候在门口站着。</p><p>她说，那个人知道你八十几块吗。</p><p>我说，知道。</p><p>她说，她知道你还去弄一千二？</p><p>我说，她让我别垫。</p><p>她说，她让你别垫，你还是垫了。</p><p>她说，那你是给自己垫的。</p><p>她说，你给自己垫的那一份，她收不到。</p><p>她说，你要想让她收到，你得先活着。</p><p>那天中午我给我妈打了饭，我一个人坐在床边吃。</p><p>手机亮了一下。</p><p>是新号。</p><p>她上线了。</p><p>她发的是：</p><p>她说，陈树跟我讲了。</p><p>我说，他怎么有你号。</p><p>她说，我那年给你的那个号，你有一次登录过我们宿舍的网。</p><p>她说，IP 我室友看见过，她跟陈树是老乡。</p><p>她说，你别管这个。</p><p>她说，你现在在干什么。</p><p>我说，吃饭。</p><p>她说，你烧退了吗。</p><p>我说，退了。</p><p>她说，你这两天不许发东西。</p><p>我说，我发了。</p><p>她说，我知道你发了。</p><p>她说，我看见那三十七个红包记录，我给你退回来。</p><p>她说，我这边今天到账了。</p><p>我说，你别转。</p><p>她说，我不是转给你。</p><p>我说，那是什么。</p><p>她说，我买了两张票。</p><p>她说，我十一月中有个展要到你们那边，我买了一张到宁城的。</p><p>她说，我在宁城待两天。</p><p>我说，你来宁城干什么。</p><p>她说，那边有一场。</p><p>我说，你什么时候告诉我。</p><p>她说，我今天告诉你。</p><p>她说，你听着。</p><p>她说，你很重要。</p><p>她说，但是你别熬了。</p><p>她说，你要是把自己熬没了，我这两千八的牙、那一千二的账、你这个本子，我全找不到人还。</p><p>她说，你不是为我熬的。</p><p>她说，你自己不承认。</p><p>她说，你现在就承认一次。</p><p>我坐在床边，手上是一个苹果。</p><p>我说，我不是为你熬的。</p><p>我说，我是因为我只有这个。</p><p>我说，我会的东西里，只有&quot;我可以不要&quot;这一样能给你。</p><p>她说，我知道。</p><p>她说，所以我不要。</p><p>她说，你不要给我这个。</p><p>她说，你给我留着，你以后要给你自己的孩子，或者给你那个真的跟你坐在一张桌上吃饭的人。</p><p>她说，你把这个东西用在你自己身上。</p><p>我说，那你把那两张票退了吧。</p><p>她说，我不退。</p><p>我说，为什么。</p><p>她说，因为我不去宁城，我这辈子就没有第二个地方可去了。</p>',160)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
